files.content:
* {
  box-sizing: border-box;
}

body {
  position: relative;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  margin: 0;
  padding: 50px;
  font-family: 'Open Sans', sans-serif;
  font-size: 18px;
  min-block-size: 100dvh;

  /* пропишите фильтр здесь */
  filter: grayscale(100%);
}

.header {
  inline-size: 100%;
}

.header__title {
  margin: 0;
  border: 1px solid #000;
  padding: 20px 0;
  color: #fd24af;
  font-weight: 800;
  font-size: 38px;
  text-align: center;
  text-transform: uppercase;
}

.menu__list {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  place-items: center;
  margin: 0;
  border: 1px solid #000;
  border-block-start: none;
  padding: 0;
  list-style: none;
  inline-size: 100%;
  block-size: 100%;
}

.menu__item {
  display: flex;
  justify-content: center;
  margin: 0;
  padding: 20px 10px;
  cursor: pointer;
  inline-size: 100%;
  block-size: 100%;
}

.menu__item:not(:last-of-type) {
  border-inline-end: 1px solid #000;
}

.menu__item a {
  position: relative;
  margin: 0;
  font-weight: 800;
  font-size: 24px;
  text-align: center;
  text-transform: uppercase;
}

.menu__item a:hover {
  opacity: 0.6;
}

.menu__item:nth-child(1) a {
  color: #80d994;
}

.menu__item:nth-child(2) a {
  color: #5f0dee;
}

.menu__item:nth-child(3) a {
  color: #feafe8;
}

.container {
  display: flex;
  border-inline-start: 1px solid #000;
  border-inline-end: 1px solid #000;
  border-block-end: 1px solid #000;
  inline-size: 100%;
}

.container img {
  display: block;
  object-fit: cover;
  object-position: center;
  inline-size: 50%;
  aspect-ratio: 380/228;
}

.container__texts {
  padding: 40px 20px;
  font-weight: 500;
  font-size: 20px;
  text-align: left;
  inline-size: 50%;
}

.container p {
  margin: 0;
}

.container:nth-of-type(1) {
  background-color: #ffc802;
}

.container:nth-of-type(2) {
  background-image: url(https://code.s3.yandex.net/web-code/images/dotted-l.svg);
}

@media (width <= 600px) {
  .header__title {
    font-size: 24px;
  }

  .menu__list {
    grid-template-columns: 1fr;
  }

  .menu__item {
    inline-size: 100%;
  }

  .menu__item:not(:last-of-type) {
    border-inline-end: none;
    border-block-end: 1px solid #000;
  }

  .menu__item a {
    font-size: 18px;
  }

  .container {
    flex-direction: column;
  }

  .container img {
    inline-size: 100%;
  }

  .container__texts {
    font-size: 16px;
    inline-size: 100%;
  }
}
